# Let's look at the lines around each match
lines = context.split('\n')
matches = []
for i, line in enumerate(lines):
    if line.strip() == 'user: Describe your ideal documentary in detail.':
        matches.append(i)

print(f"Found {len(matches)} matches at lines: {matches}")

for idx, line_num in enumerate(matches):
    print(f"\n--- Match {idx+1} at line {line_num} ---")
    # Show the user line and the next line (assistant response)
    print(f"User: {lines[line_num]}")
    if line_num + 1 < len(lines):
        print(f"Assistant: {lines[line_num + 1]}")
    else:
        print("(no following line)")
